(() => {
  // Deterministic safeguard for resolve_conversation()'s 2h inactivity
  // timeout: persist conversations.last_message_at from the inbound
  // message row just inserted by `insert message`, so timing stays
  // correct even if the DB AFTER INSERT trigger did not take effect.
  // Prefer the persisted row's real created_at; fall back to the
  // insert instant. Does NOT change lifecycle/handover behaviour.
  const resp = $node["insert message"].json;
  const row = Array.isArray(resp) ? (resp[0] || {}) : (resp || {});
  const ts = row.created_at || new Date().toISOString();
  return { last_message_at: ts };
})()
}}

parameters.jsCode:
const platform = String($json.params?.platform || "").toLowerCase();
const channelKey = String($json.params?.channelKey || "");

let text = "";
let sender_id = "";
let quick_reply_payload = null;
let is_echo = false;
let sender_name = "";   // WhatsApp pushName / Telegram first_name (webhook-provided)

// Customer -> Inbox inbound media
let has_media = false;
let media_message_type = "";   // image | document | audio
let media_mime_type = "";
let media_file_name = "";
let fb_attachment_url = "";
let tg_file_id = "";
let media_size_bytes = 0;

function mapFbType(tp) {
  if (tp === "image") return "image";
  if (tp === "audio") return "audio";
  if (tp === "video") return "document";
  if (tp === "file") return "document";
  return "";
}

if (platform === "telegram") {
  const msg =
    $json.body?.message ||
    $json.body?.edited_message ||
    $json.body?.channel_post ||
    {};

  text = msg.text || msg.caption || "";
  sender_id = String(msg.chat?.id || "");
  sender_name = String(msg.from?.first_name || msg.from?.username || "").trim();

  const mid = String(msg.message_id || "0");

  // best-effort extension from a Telegram-provided mime type
  const extFromMime = (m) => {
    m = String(m || "").split(";")[0].trim().toLowerCase();
    const MAP = {
      "image/jpeg": "jpg", "image/pjpeg": "jpg", "image/png": "png",
      "image/webp": "webp", "image/gif": "gif", "image/heic": "heic",
      "audio/ogg": "ogg", "audio/opus": "ogg", "audio/mpeg": "mp3",
      "audio/mp4": "m4a", "audio/x-m4a": "m4a", "audio/aac": "aac",
      "audio/wav": "wav", "audio/x-wav": "wav", "audio/flac": "flac",
      "video/mp4": "mp4", "video/quicktime": "mov", "video/webm": "webm",
      "video/x-matroska": "mkv",
      "application/pdf": "pdf", "application/zip": "zip",
      "application/gzip": "tgs",
      "application/vnd.openxmlformats-officedocument.wordprocessingml.document": "docx",
      "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": "xlsx",
      "application/msword": "doc", "application/vnd.ms-excel": "xls",
      "text/plain": "txt", "text/csv": "csv",
    };
    if (MAP[m]) return MAP[m];
    const sub = (m.split("/")[1] || "").replace(/^x-/, "");
    return /^[a-z0-9]{1,8}$/.test(sub) ? sub : "";
  };
  // keep an original name if it already has an extension, else add one
  const keepOrName = (original, fallbackBase, mime, fallbackExt) => {
    const o = String(original || "").trim();
    if (o) return o;
    const e = extFromMime(mime) || fallbackExt || "bin";
    return fallbackBase + "." + e;
  };

  // Telegram fills a compat `document` object on animation messages too,
  // so `animation` MUST be checked before `document`.
  if (Array.isArray(msg.photo) && msg.photo.length) {
    const largest = msg.photo[msg.photo.length - 1];
    has_media = true;
    media_message_type = "image";
    tg_file_id = String(largest.file_id || "");
    media_mime_type = "image/jpeg";           // Telegram photos are always JPEG
    media_file_name = "telegram_photo_" + mid + ".jpg";
    media_size_bytes = Number(largest.file_size) || 0;
  } else if (msg.animation) {
    has_media = true;
    media_message_type = "document";          // GIF / looping mp4 -> stored as a file
    tg_file_id = String(msg.animation.file_id || "");
    media_mime_type = msg.animation.mime_type || "video/mp4";
    media_file_name = keepOrName(msg.animation.file_name, "telegram_animation_" + mid, media_mime_type, "mp4");
    media_size_bytes = Number(msg.animation.file_size) || 0;
  } else if (msg.document) {
    has_media = true;
    media_message_type = "document";
    tg_file_id = String(msg.document.file_id || "");
    media_mime_type = msg.document.mime_type || "";
    media_file_name = keepOrName(msg.document.file_name, "telegram_document_" + mid, media_mime_type, "bin");
    media_size_bytes = Number(msg.document.file_size) || 0;
  } else if (msg.video) {
    has_media = true;
    media_message_type = "document";          // no dedicated video message_type
    tg_file_id = String(msg.video.file_id || "");
    media_mime_type = msg.video.mime_type || "video/mp4";
    media_file_name = keepOrName(msg.video.file_name, "telegram_video_" + mid, media_mime_type, "mp4");
    media_size_bytes = Number(msg.video.file_size) || 0;
  } else if (msg.audio) {
    has_media = true;
    media_message_type = "audio";
    tg_file_id = String(msg.audio.file_id || "");
    media_mime_type = msg.audio.mime_type || "audio/mpeg";
    let base = "telegram_audio_" + mid;
    const performer = String(msg.audio.performer || "").trim();
    const title = String(msg.audio.title || "").trim();
    if (title) base = performer ? (performer + " - " + title) : title;
    media_file_name = keepOrName(msg.audio.file_name, base, media_mime_type, "mp3");
    media_size_bytes = Number(msg.audio.file_size) || 0;
  } else if (msg.voice) {
    has_media = true;
    media_message_type = "audio";
    tg_file_id = String(msg.voice.file_id || "");
    media_mime_type = String(msg.voice.mime_type || "audio/ogg").split(";")[0].trim();
    media_file_name = "telegram_voice_" + mid + "." + (extFromMime(media_mime_type) || "ogg");
    media_size_bytes = Number(msg.voice.file_size) || 0;
  }
  // NOT handled this phase (reported separately, never mis-classified as text):
  //   msg.video_note (round video)  /  msg.sticker  -> fall through -> dropped
}

if (platform === "facebook" || platform === "instagram") {
  const entry = $json.body?.entry?.[0];
  const fbMessage = entry?.messaging?.[0];

  const pageId = String(entry?.id || "");
  const senderId = String(fbMessage?.sender?.id || "");

  is_echo = fbMessage?.message?.is_echo === true;

  if (is_echo || senderId === pageId || senderId === channelKey) {
    return [];
  }

  text = fbMessage?.message?.text || "";
  sender_id = senderId;
  quick_reply_payload = fbMessage?.message?.quick_reply?.payload || null;

  const atts = fbMessage?.message?.attachments;
  if (Array.isArray(atts) && atts.length) {
    const att = atts.find((a) => a && ["image", "audio", "video", "file"].includes(a.type));
    const url = att?.payload?.url || "";
    const mt = mapFbType(att?.type);
    if (att && url && mt) {
      has_media = true;
      media_message_type = mt;
      fb_attachment_url = url;
      media_mime_type = ""; // resolved from the download response in Inbound-Media-Core
      // Original filename, best-effort. Meta's file-attachment webhook
      // has no dedicated name field, but some payloads carry
      // payload.title / payload.name, and a Messenger CDN URL sometimes
      // ends in a real "name.ext" segment. Anything without a real
      // extension is junk (a hash, or the empty segment before
      // "/?params") -> leave media_file_name empty so Inbound-Media-Core
      // uses the download's Content-Disposition header / a proper
      // MIME->extension map instead of fabricating "<type>_attachment".
      const hasRealExt = (s) => /\.[a-z0-9]{1,8}$/i.test(String(s || "").trim());
      let picked = "";
      const titleCand = att.payload && (att.payload.title || att.payload.name);
      if (hasRealExt(titleCand)) {
        picked = String(titleCand).trim();
      } else {
        try {
          const segs = new URL(url).pathname.split("/").filter(Boolean);
          const last = segs.length ? decodeURIComponent(segs[segs.length - 1]) : "";
          if (hasRealExt(last)) picked = last;
        } catch (e) {}
      }
      media_file_name = picked;
    }
  }
}

// Ignore only when there is neither text nor media (delivery/read receipts,
// non-message Telegram updates, etc). Normal text messages are unchanged.
if (!text && !has_media) {
  return [];
}

return {
  platform,
  channelKey,
  text,
  sender_id,
  quick_reply_payload,
  is_echo,
  sender_name,

  has_media,
  media_message_type,
  media_mime_type,
  media_file_name,
  media_size_bytes,
  fb_attachment_url,
  tg_file_id,

  raw_body: $json.body || $json
};

const base = $items("Code in JavaScript1", 0, 0)[0].json;
const integration = $items("client_feature", 0, 0)[0].json;
const prep = $items("prepare_conversation", 0, 0)[0].json;

const replies = $input.all().map(item => item.json);
//const text = String(base.text || "").toLowerCase().trim();
const text = String(base.quick_reply_payload || base.text || "").toLowerCase().trim();

const clients = integration.clients || integration.client || {};

const welcomeMessage =
  prep.welcome_message ||
  clients.welcome_message ||
  null;

// (welcome-priority short-circuit removed — Welcome is prepended in state_payload
// for AUTO/AI new conversations; welcome_only sends it via its own path)

// 2) Auto replies only
let match = null;

for (const r of replies) {
  const trigger = String(r.trigger_text || "").toLowerCase().trim();
  if (trigger && text.includes(trigger)) {
    match = r.reply_text;
    break;
  }
}

return [
  {
    json: {
      platform: base.platform,
      channelKey: base.channelKey,
      text: base.text,
      sender_id: base.sender_id,
      client_id: integration.client_id,
      config: integration.config || {},
      reply_text: match,
      matched: !!match,
      is_welcome: false,
      is_closing: false,
      next_step: null,
      current_step: prep.current_step || null,
      conversation_status: prep.conversation_status || "active",
      conversation_id: prep.conversation_id
    }
  }
];

