(() => {
  // AI eligibility (AI Engine V1 — decoupled from the legacy
  // ai_auto_reply integration). Reaching this node already means:
  //   - the channel account has reply_mode == "ai" (Reply Mode Router)
  //   - an active, non-expired subscription exists (validate_subscription)
  // Here we only enforce the plan's AI allowance:
  //   ai_replies_limit == null / undefined / ""  -> UNLIMITED -> allowed
  //   finite limit                               -> ai_replies_used < limit
  const raw = $node["get_active_subscription"].json;
  const sub = Array.isArray(raw) ? (raw[0] || {}) : (raw || {});
  const plan = sub.plans || {};
  const limit = plan.ai_replies_limit;
  if (limit === null || limit === undefined || limit === "") return true;
  const lim = Number(limit);
  if (!Number.isFinite(lim)) return true;
  const used = Number(sub.ai_replies_used) || 0;
  return used < lim;
})()
}}

