let ccDecision = null;
try {
  ccDecision = ($items("closing_confirm_gate", 0, 0)[0] || {}).json?.decision || null;
} catch (e) {}
const cancelStaleClose =
  ccDecision === "substantive" && prep.current_step === "closing_confirm";

let mergedStep = norm.current_step || null;
if (cancelStaleClose && (mergedStep === "closing_confirm" || mergedStep === null)) {
  mergedStep = null;
}

return [
  {
    json: {
      ...norm,
      config: config, // 👈 هذا الحل
      client_id: prep.client_id,
      sender_id: prep.sender_id,
      platform: prep.platform,
      conversation_id: prep.conversation_id,
      conversation_status: norm.conversation_status || "active",
      current_step: mergedStep,
      reply_from: prep.reply_from || norm.reply_from,

    from_norm: norm.reply_from,
    from_prep: prep.reply_from,
    selected: prep.reply_from || norm.reply_from
    }
  }
];


