const replyText = $json.reply ?? $json.reply_text ?? "";

const status = $json.conversation_status ?? $json.next_status ?? "active";

const step = $json.current_step ?? $json.next_step ?? null;

const quickReplies =
  $json.quick_replies ??
  $items("format_quick_replies", 0, 0)[0]?.json?.quick_replies ??
  null;

const message = {
  text: replyText
};

const blockedSteps = [
  "waiting_for_contact",
  "reopen_confirm"
];

const canShowQuickReplies =
  status !== "closed" &&
  step !== "done" &&
  !blockedSteps.includes(step) &&
  Array.isArray(quickReplies) &&
  quickReplies.length > 0;


if (canShowQuickReplies) {
  message.quick_replies = quickReplies;
}

const replySource =
  $json.reply_source ||
  ($json.intent === "order" ? "ai" : null) ||
  ($json.intent === "human_request" ? "system" : null) ||
  "system";

const replyFrom = $json.reply_from;

console.log($json);
return [{
  json: {
    debug_reply_source: replySource,
    debug_original_reply_source: $json.reply_source,

    debug_reply_from: replyFrom,
    debug_original_reply_from: $json.reply_from,

    ...$json,
    reply: replyText,
    message,
    conversation_status: status,
    current_step: step,
    quick_replies: canShowQuickReplies ? quickReplies : null,
    reply_source: replySource,
    reply_from: replyFrom,
  }
}];

// A usable quick-reply row needs a non-empty title AND a non-empty payload.
// Facebook rejects a text quick reply with no title ((#100) Title is
// required for this quick reply content type). get_quick_replies has
// alwaysOutputData, so a client with NO configured quick replies arrives
// here as a single empty {} item -- filtering it (and any malformed row)
// out makes quick_replies correctly come back as [].
const isValidRow = (r) =>
  r &&
  typeof r === "object" &&
  typeof r.title === "string" && r.title.trim() !== "" &&
  typeof r.payload === "string" && r.payload.trim() !== "";

const rows = $input.all().map(i => i.json).filter(isValidRow);

const base = $items("Code in JavaScript1", 0, 0)[0]?.json || {};
const lastPayload = base.quick_reply_payload || null;

let hiddenPayloads = [];
let selectedRow = null;

if (lastPayload) {
  selectedRow = rows.find(r => r.payload === lastPayload) || null;

  // إذا الخيار المختار هو تواصل بشري → لا تعرض أي خيارات بعدها
  if (selectedRow?.action_type === "human_request") {
    return [{
      json: {
        quick_replies: [],
        last_payload: lastPayload,
        hidden_payloads: [],
        selected_action_type: selectedRow.action_type
      }
    }];
  }

  hiddenPayloads = [
    lastPayload,
    ...(Array.isArray(selectedRow?.hide_after_payloads)
      ? selectedRow.hide_after_payloads
      : [])
  ];
}

const filteredRows = rows.filter(r => {
  if (!lastPayload) return true;
  return !hiddenPayloads.includes(r.payload);
});

const quick_replies = filteredRows.map(r => ({
  content_type: "text",
  title: r.title,
  payload: r.payload
}));

return [{
  json: {
    quick_replies,
    last_payload: lastPayload,
    hidden_payloads: hiddenPayloads,
    selected_action_type: selectedRow?.action_type || null
  }
}];

