  // AI-Agent-Core (waiting_human / closed). It never writes
  // conversation_status back to "active" from state captured before the
  // AI turn -- that would revert a handover/close the backend applied.
  const payload = {
    current_step: state.current_step || null
  };

  if (state.conversation_status === "closed") {
    payload.conversation_status = "closed";
    payload.closed_at = $now;
  } else if (state.conversation_status === "waiting_human") {
    payload.conversation_status = "waiting_human";
  }

  return payload;
})()
}}

