const base = $items("Code in JavaScript1", 0, 0)[0].json;
const integration = $items("client_feature", 0, 0)[0].json;
const prep = $items("prepare_conversation", 0, 0)[0].json;

let messageId = null;

try {
  messageId = $items("insert message", 0, 0)[0]?.json?.id || null;
} catch (e) {
  messageId = null;
}

// Scoped closing_confirm follow-up: when a SUBSTANTIVE message cancels a
// pending "closing_confirm" (see closing_confirm_gate), the AI must not see
// the stale step this turn — otherwise it may re-render the close-confirm
// prompt/buttons. Only this exact case is overridden; every other step is
// passed through unchanged.
let stepForTurn = prep.current_step || null;
try {
  const ccDecision = ($items("closing_confirm_gate", 0, 0)[0] || {}).json?.decision || null;
  if (ccDecision === "substantive" && stepForTurn === "closing_confirm") {
    stepForTurn = null;
  }
} catch (e) {}

return [{
  json: {
    conversation_id: prep.conversation_id,
    client_id: prep.client_id || integration.client_id,
    current_message: base.text || "",
    message_id: messageId,
    current_step: stepForTurn,
    channel: base.platform || "whatsapp"
  }
}];

const base = $items("Code in JavaScript1", 0, 0)[0].json;
const integration = $items("client_feature", 0, 0)[0].json;
const prep = $items("prepare_conversation", 0, 0)[0].json;

const clients = integration.clients || integration.client || {};

// --- Robust AI-Agent-Core result parsing -----------------------------
// AI-Agent-Core (Build Result) normally returns a flat object:
//   { reply, intent, action, quick_reply_action, conversation_status, ... }
// But the model sometimes answers as a JSON blob instead of plain text +
// a trailing "#intent:" marker; Resolve Intent then JSON.stringify()s it,
// so `reply` can arrive as a raw JSON STRING (or an object, or wrapped in
// response/result/output/data). None of that may reach the customer.
function asObject(v) {
  if (v && typeof v === "object" && !Array.isArray(v)) return v;
  if (typeof v === "string") {
    const s = v.trim();
    if (s.startsWith("{") && s.endsWith("}")) {
      try {
        const p = JSON.parse(s);
        if (p && typeof p === "object" && !Array.isArray(p)) return p;
      } catch (e) {}
    }
  }
  return null;
}

// Drill through known nesting wrappers to the object that carries `reply`.
function unwrap(v) {
  let cur = asObject(v) || (v && typeof v === "object" ? v : {});
  const seen = new Set();
  for (let i = 0; i < 6; i++) {
    if (!cur || typeof cur !== "object" || seen.has(cur)) break;
    seen.add(cur);
    const carries =
      cur.reply !== undefined || cur.text !== undefined ||
      cur.message !== undefined || cur.intent !== undefined ||
      cur.conversation_status !== undefined;
    if (carries) break;
    const inner =
      asObject(cur.response) || asObject(cur.result) || asObject(cur.data) ||
      asObject(cur.json) || asObject(cur.output) || asObject(cur.body);
    if (!inner) break;
    cur = inner;
  }
  return cur || {};
}

const c = unwrap($json);
const embedded = asObject(c.reply) || {};

// Resolve the final plain reply text.
function resolveReplyText(node) {
  let r = node.reply;
  const rObj = asObject(r);
  if (rObj) r = rObj.reply ?? rObj.text ?? rObj.message ?? "";
  if (r == null || r === "") r = node.text ?? node.message ?? "";
  if (r && typeof r === "object") r = r.reply ?? r.text ?? r.message ?? "";
  let s = String(r == null ? "" : r).trim();
  const sObj = asObject(s);
  if (sObj) s = String(sObj.reply ?? sObj.text ?? sObj.message ?? "").trim();
  // strip a trailing "#intent: xxx" marker that leaked past Resolve Intent
  s = s.replace(/\s*#intent:\s*[a-z_]+\s*$/i, "").trim();
  return s;
}

const parsedReply = resolveReplyText(c);

const coreIntent =
  (c.intent && c.intent !== "unknown") ? c.intent
  : (embedded.intent || c.intent || "unknown");
const coreAction = c.action != null ? c.action : (embedded.action ?? null);
const coreQuickAction = c.quick_reply_action || embedded.quick_reply_action || null;

// --- Non-downgrade lifecycle resolution -------------------------------
// /api/ai-tools owns authoritative conversation lifecycle. The parent may
// only HOLD or ADVANCE lifecycle state -- never write conversation_status
// back to a LOWER state than what it observed (prep) or what the Core
// reported (core).
const LIFECYCLE_RANK = { active: 0, waiting_human: 1, closed: 2 };
const prepStatus = prep.conversation_status || "active";
let coreStatus = c.conversation_status || embedded.conversation_status || null;

if (!coreStatus && (coreIntent === "human_request" || coreAction === "human_handover")) {
  coreStatus = "waiting_human";
}

const conversationStatus = [prepStatus, coreStatus]
  .filter((s) => s && LIFECYCLE_RANK[s] !== undefined)
  .reduce((acc, s) => (LIFECYCLE_RANK[s] > LIFECYCLE_RANK[acc] ? s : acc), "active");

const currentStep =
  c.current_step !== undefined && c.current_step !== null
    ? c.current_step
    : (prep.current_step || null);

let quickReplies = null;
if (coreQuickAction === "closing_confirm") {
  quickReplies = [
    { content_type: "text", title: "نعم", payload: "CLOSE_CONVERSATION" },
    { content_type: "text", title: "كمل المحادثة", payload: "CONTINUE_CONVERSATION" }
  ];
}

const reply =
  parsedReply ||
  clients.default_reply ||
  integration.default_reply ||
  "شكراً لتواصلك معنا 🙏 سيتم الرد عليك بأقرب وقت ممكن";

return [{
  json: {
    platform: base.platform,
    channelKey: base.channelKey,
    text: base.text,
    sender_id: base.sender_id,
    client_id: integration.client_id,
    config: integration.config || {},

    conversation_id: prep.conversation_id,

    reply,
    intent: coreIntent || "unknown",
    action: coreAction,

    next_step: currentStep,
    current_step: currentStep,
    conversation_status: conversationStatus,

    quick_replies: quickReplies,

    lead_name: null,
    lead_phone: null,

    reply_source: "ai",
    reply_from: "ai"
  }
}];

const cj1 = $items("Code in JavaScript1", 0, 0)[0].json;
const prep = $items("prepare_conversation", 0, 0)[0].json;
const cfg = prep.config || {};
const platform = cj1.platform;
const reg = $items("Parse Workflow Registry", 0, 0)[0]?.json || {}; // central n8n workflow registry

return [{
  json: {
    platform: platform,
    message_type: cj1.media_message_type || "",
    client_id: prep.client_id,
    conversation_id: prep.conversation_id,
    provider_mime: cj1.media_mime_type || "",
    provider_file_name: cj1.media_file_name || "",
    provider_size_bytes: Number(cj1.media_size_bytes) || 0,
    caption: cj1.text || "",
    wa_base_url: "",
    wa_api_key: "",
    wa_instance: "",
    wa_message_key: "{}",
    wa_message_raw: "",
    wa_inline_base64: "",
    tg_bot_token: platform === "telegram" ? String(cfg["Bot Token"] || cfg.bot_token || cfg.token || "") : "",
    tg_file_id: platform === "telegram" ? String(cj1.tg_file_id || "") : "",
    fb_attachment_url: (platform === "facebook" || platform === "instagram") ? String(cj1.fb_attachment_url || "") : "",
    fb_page_token: (platform === "facebook" || platform === "instagram") ? String(cfg["Page Access Token"] || cfg.page_access_token || "") : "",
    inbound_media_core_workflow_id: reg.inbound_media_core_workflow_id || ""
  }
}];

const cj1 = $items("Code in JavaScript1", 0, 0)[0].json;
const cf = $items("client_feature", 0, 0)[0].json;
const prep = $items("prepare_conversation", 0, 0)[0].json;
const incoming = $json || {};

const mediaOk = !!(incoming && incoming.ok === true && incoming.media_path);

const row = {
  client_id: cf.client_id || cj1.client_id,
  channel: cj1.platform,
  sender: cj1.sender_id,
  message: cj1.text || "",
  direction: "inbound",
  conversation_id: prep.conversation_id
};

if (mediaOk) {
  row.message_type = incoming.message_type || "document";
  row.media_path = incoming.media_path;
  row.media_mime_type = incoming.media_mime_type || null;
  row.media_file_name = incoming.media_file_name || null;
  row.media_size_bytes = incoming.media_size_bytes || null;
} else {
  // No media, or media ingest failed. Never fabricate a successful
  // attachment. Preserve the caption/text; a media-only message whose
  // download failed still creates one inbound row so the event is not lost.
  row.message_type = "text";
  if (cj1.has_media === true) {
    console.log("inbound_media_ingest_failed " + JSON.stringify({
      conversation_id: prep.conversation_id,
      platform: cj1.platform,
      media_message_type: cj1.media_message_type || null,
      error_code: (incoming && incoming.error_code) || "NO_CORE_RESULT",
      error_detail: (incoming && (incoming.error_detail || incoming.message)) || null
    }));
  }
}

return [{ json: row }];

const rows = $input.all().map((i) => i.json).filter(Boolean);

// Central n8n workflow registry (Admin -> Settings -> System). Failure-safe:
// if the read errored or a key is missing, the value stays "" and the
// Execute Workflow node degrades via its own onError handler.
const m = {
  ai_agent_core_workflow_id: "",
  inbound_media_core_workflow_id: ""
};

for (const r of rows) {
  if (r && typeof r.key === "string" && Object.prototype.hasOwnProperty.call(m, r.key)) {
    m[r.key] = typeof r.value === "string" ? r.value.trim() : "";
  }
}

return [{ json: m }];

// Deterministic closing-confirm gate.
// Runs right after the human hard-stop and BEFORE Welcome / Reply Mode /
// AI processing, and ONLY acts when the conversation is already at
// current_step === "closing_confirm". Emits exactly one of:
//   confirm     -> customer confirmed -> close deterministically (no AI)
//   continue    -> customer declined / "keep going" -> clear the step (no AI)
//   substantive -> a real message during closing_confirm -> normal AI path
//   normal      -> not at closing_confirm -> normal path, untouched
// Matching is CONSERVATIVE: the whole normalized message must consist only
// of a small approved affirmative/negative/sign-off vocabulary. No
// substring test, no AI classification.
const prep = $items("prepare_conversation", 0, 0)[0].json || {};
const base = $items("Code in JavaScript1", 0, 0)[0].json || {};

const step = prep.current_step || null;
const payload = prep.quick_reply_payload || base.quick_reply_payload || null;

if (step !== "closing_confirm") {
  return [{ json: { decision: "normal" } }];
}

const CONTINUE_REPLY = {
  decision: "continue",
  reply: "تمام 👍 كمّل رسالتك.",
  conversation_status: "active",
  current_step: null,
  intent: "unknown",
  action: null,
  reply_source: "system",
  reply_from: "system",
  quick_replies: []
};

// Quick-reply button payloads are unambiguous.
if (payload === "CLOSE_CONVERSATION") {
  return [{ json: { decision: "confirm", _cc: "payload" } }];
}
if (payload === "CONTINUE_CONVERSATION") {
  return [{ json: { ...CONTINUE_REPLY, _cc: "payload" } }];
}

const norm = String(base.text || "")
  .toLowerCase()
  .replace(/\u0640/g, "")
  .replace(/[\u064B-\u0652\u0670]/g, "")
  .replace(/[إأآ]/g, "ا")
  .replace(/ى/g, "ي")
  .replace(/ة/g, "ه")
  .replace(/ؤ/g, "و")
  .replace(/ئ/g, "ي")
  .replace(/[^\p{L}\p{N}\s]/gu, " ")
  .replace(/\s+/g, " ")
  .trim();

const tokens = norm ? norm.split(" ") : [];

const AFFIRM = new Set([
  "نعم","ايه","اه","ايوه","ايوا","اجل","اكيد","موافق","جاهز","تمام","تم",
  "خلص","ماشي","حاضر","اوك","اوكي","اوكيه",
  "yes","yeah","yep","yup","ok","okay","sure","done"
]);
const NEGATE = new Set([
  "لا","كمل","كملي","استني","استنا","انتظر","لحظه","دقيقه","بعدين","مش","لسه","لسا",
  "no","wait","later","not"
]);
const FILLER = new Set([
  "شكرا","مشكور","مشكوره","تسلم","تسلمو","يسلمو","يعطيك","العافيه","الله",
  "المحادثه","المحادثة","الحديث","حبيبي","اخي","استاذ",
  "thanks","thank","you","the","chat","please"
]);

if (tokens.length === 0 || tokens.length > 5) {
  return [{ json: { decision: "substantive", _cc: "len" } }];
}

const hasAffirm = tokens.some((t) => AFFIRM.has(t));
const hasNegate = tokens.some((t) => NEGATE.has(t));
const allKnown = tokens.every((t) => AFFIRM.has(t) || NEGATE.has(t) || FILLER.has(t));

if (allKnown && hasAffirm && !hasNegate) {
  return [{ json: { decision: "confirm", _cc: "typed" } }];
}
if (allKnown && hasNegate && !hasAffirm) {
  return [{ json: { ...CONTINUE_REPLY, _cc: "typed" } }];
}

return [{ json: { decision: "substantive", _cc: "mixed" } }];

// Deterministic close confirmed. The lifecycle write already happened in
// closing_confirm_close (POST /api/ai-tools close_conversation confirmed:true
// -> waiting_human + closing_confirmed). This only carries a warm closing
// reply into the existing send pipeline (merge_for_state -> state_payload
// -> sync_conversation_v2 -> ... -> send -> insert auto reply). reply_from
// "system" so update_usage consumes no AI/auto quota. quick_replies [] so
// state_payload attaches no buttons.
return [{
  json: {
    reply: "تمام، شكراً لتواصلك معنا 🙏 سعدنا بخدمتك، وإحنا موجودين إذا احتجت أي شي.",
    conversation_status: "waiting_human",
    current_step: "closing_confirmed",
    intent: "closing",
    action: "close_confirmed",
    reply_source: "system",
    reply_from: "system",
    quick_replies: []
  }
}];
